import json
import collections

map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])
travel_mode = input_data['travel_mode']

def find_path():
    impassable = set()
    water_tiles = set()
    ramps = {(23, 3), (15, 3), (11, 13), (25, 9)}
    max_x, max_y = 30, 18

    if map_id == "0_228":
        for y in range(6, 16):
            water_tiles.add((8, y))
            water_tiles.add((9, y))
        for x in [10, 11]:
            water_tiles.add((x, 14))
            water_tiles.add((x, 15))
        for y in [6, 7]:
            for x in range(10, 14):
                water_tiles.add((x, y))
        for y in range(4, 9):
            water_tiles.add((14, y))
            water_tiles.add((15, y))
        water_tiles.update(ramps)

        impassable.update([
            (17, 13), (14, 14), (13, 13), (13, 14), (15, 15),
            (12, 13), (12, 14), (12, 15), (10, 13), (16, 13),
            (7, 5), (7, 6), (8, 5), (9, 5), (10, 5), (11, 5), (12, 5), (13, 5),
            (14, 10), (14, 11), (15, 10), (15, 11), (16, 12), (16, 13), (16, 15),
            (14, 13),
            (9, 3), (10, 3), (11, 3), (12, 3), (13, 3), (14, 3), (16, 3), (17, 3), (18, 3),
            (2, 13), (4, 0), (4, 1), (4, 2), (4, 3),
            (3, 0), (3, 1), (3, 2), (3, 3)
        ])
        impassable.add((19, 15))
        for x in range(7, 15):
            impassable.add((x, 16))
        for x in range(18, 21):
            impassable.add((x, 16))
        for x in range(17, 23):
            impassable.add((x, 17))
        for x in range(0, 2):
            impassable.add((x, 17))
        for x in range(4, 8):
            impassable.add((x, 15))
        impassable.update([(3, 14), (4, 14), (7, 14)])
        for x in range(3, 7):
            impassable.add((x, 13))
        for x in range(3, 13):
            impassable.add((x, 3))
        for x in range(6, 13):
            impassable.add((x, 4))
        for y in range(0, 4):
            impassable.add((4, y))
        for y in range(4, 11):
            for x in range(1, 4):
                impassable.add((x, y))
        if travel_mode == "foot":
            impassable.update(water_tiles - ramps)

    elif map_id == "0_226":
        # Definitely verified impassable coordinates on Map 0_226:
        impassable.update([
            (13, 11), (16, 13), (17, 7), (13, 7), (16, 8), (22, 9),
            (2, 1), (2, 2), (2, 3), (2, 12), (2, 9), (1, 11), (3, 12),
            (2, 16), (3, 16)
        ])
        # Row 8 across columns 3 to 12
        for x in range(3, 13):
            impassable.add((x, 8))
        # Boundary walls and other solid rock walls that are visible on screen:
        # Row 0:
        for x in range(1, 7):
            impassable.add((x, 0))
        for x in range(10, 15):
            impassable.add((x, 0))
        # Row 1:
        impassable.add((10, 1))
        # Row 2:
        for x in range(4, 11):
            impassable.add((x, 2))
        impassable.add((14, 2))
        # Row 3:
        impassable.add((10, 3))
        # Row 4:
        for x in range(1, 9):
            impassable.add((x, 4))
        impassable.add((10, 4))
        for x in range(11, 15):
            impassable.add((x, 4))
        # Row 5:
        impassable.add((8, 5))
        # Row 6:
        for x in range(0, 6):
            impassable.add((x, 6))
        impassable.add((8, 6))
        impassable.add((9, 6))
        impassable.add((10, 6))
        impassable.add((11, 6))
        impassable.add((12, 6))
        # Row 7:
        impassable.add((0, 7))
        for x in range(12, 15):
            impassable.add((x, 7))

    def is_passable(x, y):
        if (x, y) in impassable:
            return False
        if travel_mode == "surf":
            return (x, y) in water_tiles
        else:
            return (x, y) not in (water_tiles - ramps)

    warps = {
        "0_228": {(24, 17), (23, 7), (3, 11), (7, 1), (1, 3)},
        "0_226": {(29, 1), (22, 6), (3, 11), (1, 3), (9, 1)}
    }.get(map_id, set())

    queue = collections.deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    while queue:
        cx, cy, path = queue.popleft()
        if (cx, cy) == (target_x, target_y):
            return path
        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy
            if not (0 <= nx < max_x and 0 <= ny < max_y):
                continue
            if (nx, ny) in warps and (nx, ny) != (target_x, target_y):
                continue
            if not is_passable(nx, ny):
                continue
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, path + [move]))
    return None

path = find_path()
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
